// Modelo de juguete: 3 respuestas (A, B, C) intercaladas en una misma conexión.
// Cada respuesta son 4 paquetes; los paquetes salen uno por milisegundo en rueda (A1 B1 C1 A2 B2 C2 ...).
// Latencia de ida: 20 ms. Se pierde un paquete (el 2.º de B) y su retransmisión llega 40 ms después (un RTT más).
const LAT = 20, RTT = 40, POR_FLUJO = 4;
const flujos = ['A', 'B', 'C'];
const paquetes = [];
for (let i = 1; i <= POR_FLUJO; i++) for (const f of flujos) paquetes.push({ f, i });
paquetes.forEach((p, k) => {
  p.llegada = k + LAT;                         // sin pérdidas, llega a los 20 ms de salir
  if (p.f === 'B' && p.i === 2) p.llegada += RTT; // el perdido llega tarde (retransmisión)
});

// TCP: entrega ordenada de TODO el flujo de bytes. Un paquete no se entrega hasta que llegaron todos los anteriores.
let maxLlegada = 0;
const entregaTCP = paquetes.map((p) => (maxLlegada = Math.max(maxLlegada, p.llegada)));
// QUIC: el orden se exige por flujo. Un paquete espera solo a los anteriores de su mismo flujo.
const entregaQUIC = paquetes.map((p, k) => Math.max(...paquetes.filter((q) => q.f === p.f && q.i <= p.i).map((q) => q.llegada)));

function termina(entrega) {
  const r = {};
  paquetes.forEach((p, k) => { r[p.f] = Math.max(r[p.f] || 0, entrega[k]); });
  return r;
}
console.log('Sin pérdidas, cada respuesta termina cerca de los', LAT + 9 + ' a ' + (LAT + 11), 'ms');
console.log('Con TCP  (HTTP/2):', JSON.stringify(termina(entregaTCP)));
console.log('Con QUIC (HTTP/3):', JSON.stringify(termina(entregaQUIC)));
